// ── Busca multi-token: "sup ret" encontra "Supino Reto" ──────────────────────
function matchTokens(query, ...fields){
  if(!query) return true;
  const tokens = query.toLowerCase().split(/\s+/).filter(Boolean);
  const text   = fields.join(' ').toLowerCase();
  return tokens.every(t => text.includes(t));
}
function renderExercicios(){
  initExerciciosScreen();
  const q   = ($('ex-search')||{}).value?.toLowerCase()||'';
  const fGp = ($('ex-f-gp')||{}).value||'';
  const fNv = ($('ex-f-nv')||{}).value||'';
  const fRs = ($('ex-f-res')||{}).value||'';
  const fTp = ($('ex-f-tp')||{}).value||'';
  const fCad = ($('ex-f-cad')||{}).value||'';
  const NV_FULL = {I:'Iniciante',M:'Intermediário',A:'Avançado'};

  const lista = VAULT_EX.filter(e=>{
    const g = e.g || (e.gp||'').split('|')[0].trim();
    if(q && !matchTokens(q, e.n, g, e.tp||'', e.ind||'', e.padrao||'')) return false;
    if(fGp && g !== fGp) return false;
    if(fNv && NV_FULL[e.nv] !== fNv) return false;
    if(fRs && e.r !== fRs && e.res !== fRs) return false;
    if(fTp && e.tp !== fTp) return false;
    if(fCad && e.cad !== fCad) return false;
    return true;
  });

  const lbl = $('ex-count-label'); if(lbl) lbl.textContent = lista.length+' exercícios';
  const tbody = $('ex-tbody'); if(!tbody) return;
  const empty = $('ex-empty');
  
  if(!lista.length){ tbody.innerHTML=''; if(empty) empty.classList.remove('hidden'); return; }
  if(empty) empty.classList.add('hidden');

  // Render em lotes para não travar
  tbody.innerHTML='';
  const MAX_RENDER = 200;
  const slice = lista.slice(0, MAX_RENDER);
  slice.forEach((e,i)=>{
    const tr = document.createElement('tr');
    const NV_FULL2 = {I:'Iniciante',M:'Intermediário',A:'Avançado'};
    const nv_label = NV_FULL2[e.nv]||e.nv;
    const nv_c2 = {I:'badge-green',M:'badge-amber',A:'badge-red'}[e.nv]||'badge-gray';
    const nv_badge = `<span class="badge ${nv_c2}" style="font-size:10px">${nv_label}</span>`;
    const eq_arr = Array.isArray(e.eq) ? e.eq : (e.eq||'').split('|').map(s=>s.trim()).filter(Boolean);
    const equips = eq_arr.slice(0,2).join(', ') + (eq_arr.length>2?` +${eq_arr.length-2}`:'');
    const contra = e.cnt ? `<span style="color:var(--red);font-size:10px">${e.cnt.split('|')[0].trim()}</span>` : '<span style="color:var(--text3)">—</span>';
    const gDisplay = e.g || (e.gp||'').split('|')[0].trim();
    tr.innerHTML = `
      <td style="font-weight:500">${e.n}</td>
      <td style="font-size:11px;color:var(--text2)">${gDisplay}</td>
      <td style="font-size:11px;color:var(--text3)">${e.padrao||e.pad||'—'}</td>
      <td style="font-size:11px"><span class="badge badge-gray" style="font-size:10px">${e.r||e.res||'—'}</span></td>
      <td style="font-size:11px;color:var(--text3)">${equips||'—'}</td>
      <td>${nv_badge}</td>
      <td style="font-size:11px;color:var(--text3)">${e.tp||'—'}</td>
      <td>${contra}</td>
      <td><button class="btn btn-ghost btn-sm" style="font-size:11px" onclick="verExercicio(${i+0})">Ver</button></td>`;
    tr.dataset.idx = VAULT_EX.indexOf(e);
    tbody.appendChild(tr);
  });
  if(lista.length > MAX_RENDER){
    const tr = document.createElement('tr');
    tr.innerHTML = `<td colspan="9" style="text-align:center;color:var(--text3);font-size:12px;padding:12px">Mostrando ${MAX_RENDER} de ${lista.length}. Use os filtros para refinar.</td>`;
    tbody.appendChild(tr);
  }
}

// Cache da lista atual para Ver
let _exListaAtual = [];
function renderExerciciosComCache(){
  const q   = ($('ex-search')||{}).value?.toLowerCase()||'';
  const fGp = ($('ex-f-gp')||{}).value||'';
  const fNv = ($('ex-f-nv')||{}).value||'';
  const fRs = ($('ex-f-res')||{}).value||'';
  const fTp = ($('ex-f-tp')||{}).value||'';
  _exListaAtual = VAULT_EX.filter(e=>{
    const g2 = e.g || (e.gp||'').split('|')[0].trim();
    if(q && !matchTokens(q, e.n, g2, e.tp||'', e.ind||'', e.padrao||'')) return false;
    if(fGp && !e.gp.includes(fGp)) return false;
    if(fNv && e.nv !== fNv) return false;
    if(fRs && e.res !== fRs) return false;
    if(fTp && e.tp !== fTp) return false;
    return true;
  });
}

function verExercicio(localIdx){
  renderExerciciosComCache();
  const e = _exListaAtual[localIdx] || VAULT_EX[localIdx];
  if(!e) return;
  $('modal-ex-nome').textContent = e.n;
  const NV_FULL = {I:'Iniciante',M:'Intermediário',A:'Avançado'};
  const nv_label = NV_FULL[e.nv] || e.nv;
  const nv_c = {I:'badge-green',M:'badge-amber',A:'badge-red'}[e.nv]||'badge-gray';
  const eq_html = Array.isArray(e.eq) && e.eq.length
    ? e.eq.map(eq=>`<span class="badge badge-gray" style="font-size:11px">${eq}</span>`).join('')
    : '<span style="color:var(--text3)">—</span>';
  $('modal-ex-body').innerHTML = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px">
      <div class="param-block">
        <div class="param-key">Grupo Principal</div>
        <div class="param-val">${e.g || e.gp || '—'}${e.p ? ' / ' + e.p : ''}</div>
      </div>
      <div class="param-block">
        <div class="param-key">Grupos Secundários</div>
        <div class="param-val">${e.gs||'—'}</div>
      </div>
      <div class="param-block">
        <div class="param-key">Padrão de Movimento</div>
        <div class="param-val">${e.padrao || e.pad||'—'}</div>
      </div>
      <div class="param-block">
        <div class="param-key">Tipo de Resistência</div>
        <div class="param-val">${e.r||e.res||'—'} <span style="font-family:var(--mono);font-size:10px;color:var(--text3)">(${e.r||e.res})</span></div>
      </div>
      <div class="param-block">
        <div class="param-key">Nível</div>
        <div class="param-val"><span class="badge ${nv_c}">${nv_label}</span></div>
      </div>
      <div class="param-block">
        <div class="param-key">Tipo</div>
        <div class="param-val">${e.tp||'—'}</div>
      </div>
      <div class="param-block">
        <div class="param-key">Cadeia Cinética</div>
        <div class="param-val">${e.cad||'—'}</div>
      </div>
      <div class="param-block">
        <div class="param-key">Articular</div>
        <div class="param-val">${e.art||'—'}</div>
      </div>
      <div class="param-block" style="grid-column:1/-1">
        <div class="param-key">Articulações</div>
        <div class="param-val">${e.artic||'—'}</div>
      </div>
      ${e.tempo ? `<div class="param-block">
        <div class="param-key">Tempo/rep</div>
        <div class="param-val" style="font-family:var(--mono)">${e.tempo}</div>
      </div>` : ''}

      ${e.co_g ? `<div class="param-block">
        <div class="param-key">Co-principal</div>
        <div class="param-val">${e.co_g}</div>
      </div>` : ''}
    </div>
    <div class="param-block" style="margin-bottom:10px">
      <div class="param-key">Equipamentos</div>
      <div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:6px">${eq_html}</div>
    </div>
    ${e.ind ? `<div class="alert alert-green" style="margin-bottom:8px"><strong>✅ Indicação:</strong> ${e.ind}</div>` : ''}
    ${e.cnt ? `<div class="alert alert-red" style="margin-bottom:8px"><strong>❌ Contra-indicação:</strong> ${e.cnt}</div>` : ''}
    ${e.url ? `<div style="margin-top:10px"><a href="${e.url}" target="_blank" style="color:var(--blue);font-size:13px">▶ Ver vídeo demonstrativo</a></div>` : ''}
  `;
  $('modal-ex-detail').classList.remove('hidden');
}

$('modal-ex-detail')?.addEventListener('click', function(ev){ if(ev.target===this) this.classList.add('hidden'); });

function limparFiltrosEx(){
  const ids = ['ex-search','ex-f-gp','ex-f-nv','ex-f-res','ex-f-tp'];
  ids.forEach(id=>{ const el=$(id); if(el) el.value=''; });
  renderExercicios();
}

