function loadLibs(){
  try { return JSON.parse(localStorage.getItem('fitcpx_libs')||'null') || gerarLibsDefault(); }
  catch(e){ return gerarLibsDefault(); }
}
function saveLibs(libs){
  try { localStorage.setItem('fitcpx_libs', JSON.stringify(libs)); } catch(e){}
}
