let _delPending=null;
function deletarItem(colecao, id){
  const nomes={'locais':'local','biblioteca':'template','distribuicao':'divisão','periodizacao':'modelo'};
  $('modal-del-msg').textContent=`Deseja excluir este ${nomes[colecao]||'item'}? Esta ação não pode ser desfeita.`;
  _delPending={colecao,id};
  $('modal-del-confirm').onclick=confirmarDeletar;
  $('modal-del-lib').classList.remove('hidden');
}
function confirmarDeletar(){
  if(!_delPending) return;
  const {colecao,id}=_delPending;
  LIBS[colecao]=LIBS[colecao].filter(x=>x.id!==id);
  saveLibs(LIBS);
  closeDelModal();
  if(colecao==='locais')       renderLocais();
  if(colecao==='biblioteca')   renderBiblioteca();
  if(colecao==='distribuicao') renderDistrib();
  if(colecao==='periodizacao') renderPeriod();
}
function closeDelModal(){ $('modal-del-lib').classList.add('hidden'); _delPending=null; }

// Fechar modais clicando fora
['modal-local','modal-bib','modal-distrib','modal-del-lib'].forEach(id=>{
  const el=$(id);
  if(el) el.addEventListener('click',function(e){ if(e.target===this){ this.classList.add('hidden'); _delPending=null; } });
});

function toggleTema(){
  const isDark = document.documentElement.classList.toggle('dark');
  const icon  = $('tema-icon');
  const label = $('tema-label');
  if(icon)  icon.textContent  = isDark ? '☀' : '🌙';
  if(label) label.textContent = isDark ? 'Claro' : 'Escuro';
  try { localStorage.setItem('acm-tema', isDark ? 'dark' : 'light'); } catch(e){}
}
(function(){
  try {
    const saved = localStorage.getItem('acm-tema');
    if(saved === 'dark'){
      document.documentElement.classList.add('dark');
      setTimeout(()=>{
        const icon  = $('tema-icon');
        const label = $('tema-label');
        if(icon)  icon.textContent  = '☀';
        if(label) label.textContent = 'Claro';
      }, 100);
    }
  } catch(e){}
})();

