function exportMD(){
  const s=getActive(); if(!s) return;
  const p=s.perfil, a=s.anamnese, pr=s.prescricao;
  let md='# '+  (p.nome||'Aluno')+'\n\n';
  md+='## Perfil\n';
  md+='- Nascimento: '+(p.nascimento||'—')+'\n';
  md+='- Sexo: '+(p.sexo||'—')+'\n';
  md+='- Modalidade: '+(p.modalidade||'—')+'\n';
  md+='- Liberação médica: '+(p.liberacao||'—')+'\n\n';
  md+='## Anamnese EF\n';
  md+='- Nível: '+(a.nivel||'—')+'\n';
  md+='- Frequência: '+(a.frequencia||'—')+'\n';
  md+='- Objetivo: '+(a.objetivo_ef||'—')+'\n';
  md+='- Peso: '+(a.peso||'—')+' kg | Altura: '+(a.altura||'—')+' cm\n';
  md+='- % Gordura: '+(a.gordura||'—')+' | Massa Magra: '+(a.magra||'—')+' kg\n\n';
  if(pr.aprovado && pr.treino){
    md+='## Prescrição\n'+pr.treino+'\n';
  }
  const blob=new Blob([md],{type:'text/markdown'});
  const url=URL.createObjectURL(blob);
  const a2=document.createElement('a');
  a2.href=url; a2.download=(p.nome||'aluno').replace(/\s+/g,'-')+'.md';
  a2.click(); URL.revokeObjectURL(url);
}

// Mapa padrão de movimento → aquecimento sugerido (Vault FASE-3 §2)
const AQUECIMENTO_PADRAO = {
  'Quadríceps':    'Agachamento ar ×15 + passada caminhando ×10/lado + leg press leve (50%) ×15',
  'Glúteos':       'Elevação quadril bodyweight ×20 + abdução quadril elástico ×15/lado',
  'Isquiossurais': 'Stiff leve (sem carga) ×15 + leg curl leve (40%) ×15 + RDL elástico ×12',
  'Peitoral':      'Flexão de braço ×10 + voador leve ×15 + rotação escapular ×10/lado',
  'Latíssimo':     'Band pull-apart ×15 + remada elástico ×15 + retração escapular ×10',
  'Deltóide':      'Círculo de ombros ×10 + elevação lateral leve ×15 + face pull elástico ×15',
  'Trapézio':      'Encolhimento sem peso ×20 + retração escap. ×10 + neck roll ×5/lado',
  'Bíceps':        'Rosca martelo elástico ×15 + supinação ×10/lado + circundução punho ×10',
  'Tríceps':       'Extensão tríceps elástico ×15 + flexão de cotovelo reversa ×10',
  'Reto Abdominal':'Prancha 20s + crunch abdominal ×15 + hollow body 10s',
  'Panturrilhas':  'Elevação unilateral sem peso ×20/lado + rotação tornozelo ×10/lado',
};

function gerarAquecimentoSessao(treino){
  const grupos = [...new Set(treino.exercicios.map(e=>e.musculo))];
  const itens = grupos
    .map(g => AQUECIMENTO_PADRAO[g])
    .filter(Boolean)
    .filter((v,i,a)=>a.indexOf(v)===i); // unique
  if(!itens.length) return '5 min esteira leve + mobilidade articular geral';
  return itens.join(' | ');
}

function exportPDF(){
  const s = getActive(); if(!s) return;
  const f = s.prescricao?._fichaObj;
  if(!f){ alert('Aprove a prescrição primeiro para gerar o PDF.'); return; }
  const nome  = s.perfil?.nome || 'Aluno';
  const data  = s.prescricao?.dataAprovacao || new Date().toLocaleDateString('pt-BR');
  const nivel = s.anamnese?.nivel || '';
  const obj   = s.prescricao?.objetivo || '';
  const modelo= s.prescricao?.modelo || '';

  // Semanas para tabela de registro de carga
  const semanas = ['Sem 1','Sem 2','Sem 3','Sem 4'];

  let treinosHtml = f.treinos.map((treino, ti) => {
    const aquec = gerarAquecimentoSessao(treino);
    const totalS = treino.exercicios.reduce((a,e)=>a+parseInt(e.series||0),0);
    const header = `<th style="background:#1a1a2e;color:#fff;font-size:9px;padding:5px 6px">#</th>
      <th style="background:#1a1a2e;color:#fff;font-size:9px;padding:5px 6px">Músculo</th>
      <th style="background:#1a1a2e;color:#fff;font-size:9px;padding:5px 6px">Exercício</th>
      <th style="background:#1a1a2e;color:#fff;font-size:9px;padding:5px 6px">Sér×Rep</th>
      <th style="background:#1a1a2e;color:#fff;font-size:9px;padding:5px 6px">Intensidade</th>
      <th style="background:#1a1a2e;color:#fff;font-size:9px;padding:5px 6px">Intervalo</th>
      ${semanas.map(s=>`<th style="background:#1a1a2e;color:#fff;font-size:9px;padding:5px 6px">${s}<br><span style="font-size:7px;opacity:.6">kg</span></th>`).join('')}`;
    const rows = treino.exercicios.map((ex, ri) => `<tr style="border-bottom:1px solid #eee">
      <td style="font-size:9px;color:#888;padding:5px 6px;text-align:center">${ri+1}</td>
      <td style="font-size:9px;padding:5px 6px">${ex.musculo}</td>
      <td style="font-size:10px;font-weight:600;padding:5px 6px">${ex.nome}
        ${ex.nota_clinica?`<br><span style="font-size:8px;color:#e67e22">${ex.nota_clinica}</span>`:''}
      </td>
      <td style="font-size:9px;font-family:monospace;padding:5px 6px;white-space:nowrap">${ex.series}×${ex.reps}</td>
      <td style="font-size:9px;padding:5px 6px">${ex.intensidade}</td>
      <td style="font-size:9px;padding:5px 6px">${ex.intervalo}</td>
      ${semanas.map(()=>'<td style="border:1px solid #ddd;min-width:28px;height:20px"></td>').join('')}
    </tr>`).join('');

    return `
      <div style="page-break-inside:avoid;margin-bottom:28px">
        <div style="display:flex;justify-content:space-between;align-items:baseline;border-bottom:2px solid #1a1a2e;padding-bottom:4px;margin-bottom:8px">
          <h2 style="margin:0;font-size:13px;color:#1a1a2e">${treino.label}</h2>
          <span style="font-size:10px;color:#888">${totalS} séries totais</span>
        </div>
        <div style="font-size:9px;color:#555;background:#f8f8f8;border-radius:4px;padding:7px 10px;margin-bottom:10px">
          <strong>🔥 Aquecimento sugerido (5–8 min):</strong> ${aquec}
        </div>
        <table style="width:100%;border-collapse:collapse;font-family:Arial,sans-serif">
          <thead><tr>${header}</tr></thead>
          <tbody>${rows}</tbody>
        </table>
        <div style="margin-top:8px;font-size:9px;color:#888;border-top:1px solid #eee;padding-top:5px">
          <strong>Volta à calma:</strong> Alongamento estático 20–30s por grupo trabalhado · Respiração diafragmática 2 min
        </div>
      </div>`;
  }).join('');

  const progHtml = `
    <div style="page-break-inside:avoid;margin-bottom:28px">
      <h2 style="font-size:13px;color:#1a1a2e;border-bottom:2px solid #1a1a2e;padding-bottom:4px;margin-bottom:10px">Progressão Semanal</h2>
      <table style="width:100%;border-collapse:collapse;font-size:10px;font-family:Arial,sans-serif">
        <thead><tr style="background:#1a1a2e;color:#fff">
          <th style="padding:6px 8px">Semana</th><th style="padding:6px 8px">Foco</th><th style="padding:6px 8px">Ajuste de Carga</th><th style="padding:6px 8px">Observações</th>
        </tr></thead>
        <tbody>
          <tr style="border-bottom:1px solid #eee"><td style="padding:6px 8px;font-family:monospace">Sem 1</td><td style="padding:6px 8px">Adaptação</td><td style="padding:6px 8px">Carga conservadora — foco na técnica</td><td style="padding:6px 8px;border:1px solid #eee"></td></tr>
          <tr style="border-bottom:1px solid #eee"><td style="padding:6px 8px;font-family:monospace">Sem 2</td><td style="padding:6px 8px">Desenvolvimento</td><td style="padding:6px 8px">+carga ou +reps conforme tolerância</td><td style="padding:6px 8px;border:1px solid #eee"></td></tr>
          <tr style="border-bottom:1px solid #eee"><td style="padding:6px 8px;font-family:monospace">Sem 3</td><td style="padding:6px 8px">Sobrecarga</td><td style="padding:6px 8px">Progressão aplicada — RPE 7–8</td><td style="padding:6px 8px;border:1px solid #eee"></td></tr>
          <tr><td style="padding:6px 8px;font-family:monospace">Sem 4</td><td style="padding:6px 8px">Deload</td><td style="padding:6px 8px">−40% volume, manter cargas</td><td style="padding:6px 8px;border:1px solid #eee"></td></tr>
        </tbody>
      </table>
    </div>`;

  const janela = window.open('','_blank');
  if(!janela){ alert('Permita pop-ups para gerar o PDF.'); return; }
  janela.document.write(`<!DOCTYPE html><html lang="pt-BR"><head>
    <meta charset="utf-8">
    <title>Ficha — ${nome}</title>
    <style>
      * { box-sizing: border-box; }
      body { font-family: Arial, sans-serif; margin: 0; padding: 20px 24px; color: #222; font-size: 10px; }
      h1 { font-size: 16px; margin: 0; }
      table { font-size: 9px; }
      @media print {
        body { padding: 10px 14px; }
        .no-print { display: none; }
        @page { margin: 1cm; }
      }
    </style>
  </head><body>
    <!-- Cabeçalho -->
    <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px;padding-bottom:10px;border-bottom:3px solid #1a1a2e">
      <div>
        <h1>${nome}</h1>
        <div style="font-size:10px;color:#555;margin-top:3px">${nivel} · ${obj} · ${modelo} · Aprovado em ${data}</div>
      </div>
      <div style="text-align:right;font-size:9px;color:#888">
        FitCPX Auto — Sistema ACM<br>Personal Trainer EF
      </div>
    </div>
    ${treinosHtml}
    ${progHtml}
    <div class="no-print" style="position:fixed;top:10px;right:10px">
      <button onclick="window.print()" style="padding:10px 20px;background:#1a1a2e;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:13px">🖨️ Imprimir / Salvar PDF</button>
    </div>
  </body></html>`);
  janela.document.close();
}

function salvarReavaliacao(){
  const s=getActive(); if(!s) return;
  if(!s.reavaliacao) s.reavaliacao={};
  s.reavaliacao.peso     = $('reav-peso')?.value||'';
  s.reavaliacao.gordura  = $('reav-gordura')?.value||'';
  s.reavaliacao.magra    = $('reav-magra')?.value||'';
  s.reavaliacao.cintura  = $('reav-cintura')?.value||'';
  s.reavaliacao.analise  = $('reav-analise')?.value||'';
  s.reavaliacao.decisao  = $('reav-decisao')?.value||'';
  s.reavaliacao.data     = new Date().toLocaleDateString('pt-BR');
  saveStudent();
  const ind=$('saved-indicator');
  if(ind){ ind.classList.remove('hidden'); setTimeout(()=>ind.classList.add('hidden'),2000); }
}


// Hook: após salvar divisão, atualizar step2 se callback pendente
// (movido pra cá porque salvarDistrib só existe depois que este arquivo carrega —
// no arquivo original monolítico isso não importava, hoisting resolvia sozinho)
const _origSalvarDistrib = salvarDistrib;
salvarDistrib = function(){
  _origSalvarDistrib();
  if(_pendingDivisaoCallback){
    _pendingDivisaoCallback = false;
    const freq = val('pr-frequencia') || '3x';
    const numDias = parseInt(freq)||3;
    _s3.divisaoOpcoes = gerarDivisoesBalanceadas(numDias);
    renderTelaDivisao();
  }
};
